  /// 指定した級（'LEVEL_10' 等）の配当漢字一覧を返す。
  /// 該当級が無ければ空リストを返す。
  static List<String> forLevel(String level) {
    final chars = _kanjiByLevel[level];
    if (chars == null) return const [];
    return chars.characters.toList();
  }
}

extension _StringCharacters on String {
  List<String> get characters {
    return runes.map((r) => String.fromCharCode(r)).toList();
  }
}
